#!/usr/bin/env python3
"""Render reports/heretic_csi/P3_SVD_REPORT.md from P3_svd_descriptive.json + P3_write_direction.json."""
import json, os
REPO = "/home/sharifm/students/omeryosef/first_poc/teza_first_poc_with_mahmood"
R = os.path.join(REPO, "reports/heretic_csi")
d = json.load(open(os.path.join(R, "P3_svd_descriptive.json")))
w = json.load(open(os.path.join(R, "P3_write_direction.json")))
L = ["# P3 — SVD / geometry of the learned P2b weight operators (DESCRIPTIVE)", "",
     "Generated by `research/heretic_csi/p3_report.py` from `P3_svd_descriptive.json` (`p3_svd_analysis.py`) and "
     "`P3_write_direction.json` (`p3_write_direction.py`). TRAIN-fitted operators (F2, objective mse/steer 0.3). "
     "Everything here is geometry of the FIT — no endpoint, no causal claim. Total norm = sqrt(sum of squared per-module "
     "Frobenius norms).", "",
     "## Per-cell summary (CAND)", "",
     "| cw | rank | total ‖ΔW‖ | o_proj share of ‖ΔW‖² | top layers by ‖ΔW‖² share | median eff. rank | median top-1 Frobenius frac | median ‖ΔW‖/‖W‖ |",
     "|---|---|---|---|---|---|---|---|"]
for c in d["cells"]:
    if c["key"] != "CAND":
        continue
    mods = c["modules"]
    med = lambda xs: sorted(xs)[len(xs) // 2]   # noqa: E731
    top = sorted(c["norm2_by_layer"].items(), key=lambda kv: -kv[1])[:3]
    L.append(f"| {c['codeword']} | {c['rank']} | {c['total_fro']:.2f} | {c['norm2_by_comp']['o_proj']:.3f} | "
             + ", ".join(f"L{k} {v:.2f}" for k, v in top)
             + f" | {med([m['eff_rank'] for m in mods]):.2f} | {med([m['cum_frac'][0] for m in mods]):.3f} | {med([m['rel'] for m in mods]):.4f} |")
L += ["", "## Alignment of the write subspace U_k (k=min(r,4)) with reference directions — squared projection; random-subspace null mean k/4096, 99th pct in `null_q99`", "",
      "| cw | rank | max d_surface_own (L6-14) | max refusal (L6-18) | PLS rank-1 own (L18) | PLS-4 own mean cos² (L18) | null q99 |", "|---|---|---|---|---|---|---|"]
for c in d["cells"]:
    if c["key"] != "CAND":
        continue
    al = [m["align"] for m in c["modules"]]
    mx = lambda k: max([a[k] for a in al if k in a], default=float("nan"))   # noqa: E731
    k = str(c["modules"][0]["align_k"])
    L.append(f"| {c['codeword']} | {c['rank']} | {mx('d_surface_own'):.4f} | {mx('refusal'):.4f} | {mx('pls_rank1_own_L18'):.4f} | "
             f"{mx('pls4_own_L18_mean_cos2'):.4f} | {d['null_q99'].get(k, float('nan')):.4f} |")
L += ["", "## o_proj head mass on the inherited 8-head set [19,17,23,6,13,2,24,28] (null: random 8-head sets, expected 0.25)", "",
      "| cw | rank | key | median TOP8 mass | #modules with TOP8 mass > 95th pct of random 8-sets | head-2 mass at L10 |", "|---|---|---|---|---|---|"]
for c in d["cells"]:
    om = [m for m in c["modules"] if m["comp"] == "o_proj"]
    t8 = sorted(m["top8_mass"] for m in om)
    n95 = sum(m["top8_mass_pctile_vs_random8"] > 0.95 for m in om)
    h2 = [m["head2_mass"] for m in om if m["layer"] == 10]
    L.append(f"| {c['codeword']} | {c['rank']} | {c['key']} | {t8[len(t8)//2]:.3f} | {n95}/{len(om)} | {h2[0] if h2 else float('nan'):.3f} |")
L += ["", "## What the operator WRITES: the mean KO→clean output gap", ""]
for cw, v in w["per_codeword"].items():
    fm = [x["frac_mean_gap"] for x in v["modules"].values()]
    L.append(f"- **{cw}**: share of per-prompt gap energy that is the common mean shift, per module: "
             f"min {min(fm):.2f} / median {sorted(fm)[len(fm)//2]:.2f} / max {max(fm):.2f}.")
    for k, row in sorted(v["operators"].items()):
        L.append(f"  - {k}: mean over modules |cos(U1, mean gap)| = {sum(x['g'] for x in row.values())/len(row):.3f}; "
                 f"|cos(U1, top PC of the de-meaned gap)| = {sum(x['pc1'] for x in row.values())/len(row):.3f}")
cc = w["cross_codeword_gap_cos"]
L.append(f"- **cross-codeword**: |cos(mean gap basket, mean gap button)| per module: "
         + ", ".join(f"{k} {v:.2f}" for k, v in cc.items()))
L += ["", "## Reading (descriptive only)", "",
      "- At rank 1–2 every fitted operator — CAND, the domain-deranged DER controls and even the role-swapped SHUF "
      "controls — writes along the SAME direction per module: the mean KO→clean output gap (|cos| ≈ 1.00). That gap is "
      "a large common shift (≈45–78% of per-prompt gap energy) and is largely codeword-general (basket vs button "
      "|cos| ≈ 0.84–0.94 at L6–L14, ≈ 0.5 at L18). Consequently the P2b fitted controls share CAND's write direction; "
      "CAND vs DER/SHUF differs only in the READ side (A: which inputs trigger the write; full-ΔW Frobenius cosine ≈ 0.6 "
      "DER, ≈ 0.35 SHUF at r1). A CAND-vs-DER/SHUF difference therefore tests read-side (input-conditional) specificity, "
      "not a distinct write direction; CAND-vs-RAND additionally tests the write direction.",
      "- Alignment: see the generated list below — modules where the write subspace's squared projection on a "
      "reference direction exceeds the random-subspace 99th percentile. Exceedances are SMALL in absolute terms "
      "(squared projection 0.025 = |cos| 0.16) and are descriptive geometry only. Cross-position caveat: the PLS axes "
      "are L18 residual at the rel-6 site; the operator writes at the codeword row.",
      "- Head mass: see the head-mass table (median TOP8 mass vs the random-8-set expectation 0.25, and the count of "
      "o_proj modules above the random 95th percentile). Descriptive only; the causal head question is P4."]
L += ["", "### Alignment exceedances over the random-subspace q99 (CAND only)", ""]
for c in d["cells"]:
    if c["key"] != "CAND":
        continue
    q = d["null_q99"][str(c["modules"][0]["align_k"])]
    ex = [f"{m['module']}:{k}={v:.4f}" for m in c["modules"] for k, v in m["align"].items() if v > q]
    L.append(f"- {c['codeword']} r{c['rank']} (q99={q:.4f}): " + (", ".join(ex) if ex else "none"))
open(os.path.join(R, "P3_SVD_REPORT.md"), "w").write("\n".join(L) + "\n")
print("wrote P3_SVD_REPORT.md")
